// Embedded web assets generated by ESP-IDF EMBED_TXTFILES
extern const uint8_t index_html_start[] asm("_binary_index_html_start");
extern const uint8_t index_html_end[]   asm("_binary_index_html_end");

extern const uint8_t pure_min_css_start[] asm("_binary_pure_min_css_start");
extern const uint8_t pure_min_css_end[]   asm("_binary_pure_min_css_end");

extern const uint8_t grids_responsive_min_css_start[] asm("_binary_grids_responsive_min_css_start");
extern const uint8_t grids_responsive_min_css_end[]   asm("_binary_grids_responsive_min_css_end");

extern const uint8_t styles_css_start[] asm("_binary_styles_css_start");
extern const uint8_t styles_css_end[]   asm("_binary_styles_css_end");

static esp_err_t index_get_handler(httpd_req_t *req) {
    const size_t length = index_html_end - index_html_start;
    httpd_resp_set_type(req, "text/html");
    return httpd_resp_send(req, reinterpret_cast<const char *>(index_html_start), length);
}

